package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionNativeBinding.*;
import org.kanger.ContextUniversalFamilyInspection.Status;
import org.kanger.enums.StorageLifecycleErrorCode;
import org.kanger.exception.ContextProductionCommitException;

/** Negative existential occurrence preserves whole-source family authority in either rule position. */
final class ContextExistentialAntecedent {
    static int checks;static final int WORK=64000000;
    static void require(boolean value,String why){++checks;if(!value)throw new AssertionError(why);}
    static void verdict(ContextUniversalCandidate.Evaluation e,boolean safe,boolean candidateRule,String rule,String candidate,String producer,String deny){
        require(e.status==(safe?Status.CONSISTENT:Status.COLLISION),"equivalent scope forms have exact family verdict: "+e.status+" / "+e.reason);
        if(safe){ContextUniversalFamilyModel.Certificate cert=e.qualification.certificate;require(cert!=null&&e.qualification.collision==null&&cert.cuts.size()==4,"all four cuts have a complete consistent family model");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut c:cert.cuts){require(c.receipt.verified&&c.receipt.input==cert.input&&c.model.ledger==c.receipt.closureStep.input,"exact closure/model/common-frontier bindings");receipts.add(c.receipt);models.add(c.model);}require(ContextUniversalFamilyModel.certify(cert.input,receipts,models,16,65536,WORK).certified,"independent model recertification over all admissible values");}
        else collision(e.qualification,e.artifact.foreign,e.artifact.staged,candidateRule,rule,candidate,producer,deny);
    }
    static void collision(ContextUniversalFamilyInspection.Result r,List<Snapshot> foreign,Snapshot staged,boolean candidateRule,String rule,String candidate,String producer,String deny){
        require(r.status==Status.COLLISION&&r.certificate==null&&r.collision!=null&&!r.collision.oppositions.isEmpty(),"complete supported contradiction");Set<Source> expectedForeign=new HashSet<>();for(Snapshot f:foreign)for(Entry e:f.primary)if(e.statement.equals(deny)||(!candidateRule&&e.statement.equals(rule)))expectedForeign.add(e.source);require(expectedForeign.size()==(candidateRule?1:2),"exact whole foreign rule/Deny provenance");Set<Source> expectedLocal=new HashSet<>();if(staged!=null)for(Entry e:staged.primary)if(e.statement.equals(candidate)||(candidateRule&&e.statement.equals(producer)))expectedLocal.add(e.source);
        for(ContextUniversalUnitProof.Proof p:r.collision.oppositions){Set<Source> local=new HashSet<>(),other=new HashSet<>();for(Source s:p.support.sources)(s.localX?local:other).add(s);require(p.dependsOnX&&p.contradiction&&p.conclusion==null&&p.support.sources.size()==3&&local.size()==(candidateRule?2:1)&&other.equals(expectedForeign),"only necessary three whole Sources, no p2/Other/marker contamination");if(staged!=null)require(local.equals(expectedLocal),"exact proposed and producer local Sources");}
    }
    static void one(boolean negative,boolean reverse,boolean nativePath,boolean nested,boolean safe,boolean candidateRule)throws Exception{
        Path dir=Files.createTempDirectory("existential-antecedent-write-");System.setProperty("user.home",dir.toString());String s=negative?"~":"",op=negative?"":"~",producer="!"+s+"p(1);",deny="!"+op+"q();",rule=nested?"!($x "+s+"p(x))->"+s+"q();":"!@x "+s+"p(x)->"+s+"q();",candidate=candidateRule?rule:(safe?"!safe(1);":producer);
        ContextSevenPremiseNativeWriteRunner.create(dir,"Bridge",candidateRule?"!bridgeMarker(2);":rule);ContextSevenPremiseNativeWriteRunner.create(dir,"Deny",candidateRule&&safe?"!denyMarker(2);":deny);ContextSevenPremiseNativeWriteRunner.create(dir,"Other","!other(2);");Set<String> settled;List<RevisionRef> pins;long afterRevision;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){
            require(f.root.compile((candidateRule?producer+" ":"")+"!"+op+"p(2);",null,false),"local original theory");for(String name:reverse?new String[]{"Other","Deny","Bridge"}:new String[]{"Bridge","Deny","Other"})f.db.connectContext(name);f.db.saveConnections(f.root);
            ContextProductionInventory before=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> origins=ContextSevenPremiseNativeWriteRunner.origins(before);long revision=f.db.getRevision();int rules=f.root.getRules().size();pins=ContextSevenPremiseNativeWriteRunner.pins(f);List<String> foreignPrints;
            try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){foreignPrints=ContextForeignAntecedentQuantifier.fingerprints(lease.inventory());ContextProductionSnapshotSession.Binding b=lease.bind(WORK,500000);require(b.foreign.size()==3,"every whole private cut bound");if(!candidateRule){Entry e=b.foreign.stream().flatMap(v->v.primary.stream()).filter(v->v.statement.equals(rule)).findFirst().get();require(e.kind==Kind.CLAUSES&&e.witnesses()==0&&e.clauses.size()==1&&e.clauses.get(0).variables.size()==1,"private existential antecedent is one whole universal clause");}}
            ContextUniversalCandidate.Evaluation diagnostic=f.db.qualifyUniversalProductionCandidate(f.root,candidate,1000,16,16,16,65536,1000000,WORK,500000,WORK);verdict(diagnostic,safe,candidateRule,rule,candidate,producer,deny);require(f.db.getRevision()==revision&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(before.fingerprint),"diagnostic preserves physical source");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(candidate,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(safe)require(failure==null,"native equivalent-form safe publication succeeds");else{require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified&&failure.getFamilyAudit().verdict!=diagnostic.qualification,"actual native conflict has fresh verified audit");collision(failure.getFamilyAudit().verdict,diagnostic.artifact.foreign,null,candidateRule,rule,candidate,producer,deny);}}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,candidate,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(safe?DB.ProductionWriteStatus.PUBLISHED:DB.ProductionWriteStatus.COLLISION)&&result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial,"fresh exact public trial/audit governs write");verdict(result.trial,safe,candidateRule,rule,candidate,producer,deny);require(result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"actual public physical references");}
            ContextProductionInventory after=ContextSevenPremiseNativeWriteRunner.inventory(f);settled=ContextSevenPremiseNativeWriteRunner.origins(after);afterRevision=f.db.getRevision();Set<String> expected=new HashSet<>(origins);if(safe)expected.add(candidate);require(settled.equals(expected)&&after.primary.size()==expected.size()&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"only whole proposed Source may publish; no foreign/derived primary imports");if(safe)require(afterRevision>revision,"safe publication advances revision");else require(afterRevision==revision&&f.root.getRules().size()==rules&&after.fingerprint.equals(before.fingerprint),"collision preserves exact revision/rules/fingerprint");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(ContextForeignAntecedentQuantifier.fingerprints(lease.inventory()).equals(foreignPrints),"every private initialized inventory unchanged");}
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){require(f.db.getRevision()>=afterRevision&&ContextSevenPremiseNativeWriteRunner.origins(ContextSevenPremiseNativeWriteRunner.inventory(f)).equals(settled)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"ordinary durable reopen retains exact whole local origins and ordered pins");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(lease.bind(WORK,500000).foreign.size()==3,"whole family binding survives durable reopen");}}
    }
    static void run(boolean negative,String marker){try{for(boolean r:new boolean[]{false,true})for(boolean p:new boolean[]{false,true})for(boolean n:new boolean[]{false,true})for(boolean s:new boolean[]{false,true})for(boolean c:new boolean[]{false,true})one(negative,r,p,n,s,c);System.out.println(marker+" checks="+(checks+ContextSevenPremiseNativeWriteRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
